"""Retain paired release evidence for the grouping engine integration."""
from pathlib import Path
from collections import Counter
from datetime import datetime, timezone
import hashlib
import io
import json
import math
import os
import re
import shutil
import statistics
import subprocess
import sys
import tarfile

REPO = Path('/Users/tdenisenko/code/logex')
BASE = 'c24d56b6caa7d7834411da0b5ac21a5a8f4158d1'
MANIFEST = Path(sys.argv[1])
ROOT = Path(sys.argv[2])
PLAN = json.loads(MANIFEST.read_text())
ROOT.mkdir(exist_ok=False)


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def output(command, cwd=REPO):
    return subprocess.check_output(command, cwd=cwd, text=True).strip()


def append(path, record):
    with path.open('a') as stream:
        stream.write(json.dumps(record) + '\n')


def stats(values):
    assert values and all(math.isfinite(v) and v >= 0 for v in values)
    return {'samples': len(values), 'median': statistics.median(values),
            'p95': sorted(values)[math.ceil(len(values) * .95) - 1]}


def artifact(log, target):
    found = []
    for line in log.read_text().splitlines():
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        if (record.get('reason') == 'compiler-artifact' and record.get('executable')
                and record['target']['name'] == target):
            found.append(record)
    assert len(found) == 1 and not found[0]['fresh'], (target, log)
    return Path(found[0]['executable'])


def counters(log):
    lines = log.read_text().splitlines()
    timing = None
    values = {}
    for index, line in enumerate(lines):
        match = re.match(r'^\s*([0-9.]+) real\s+([0-9.]+) user\s+([0-9.]+) sys\s*$', line)
        if match:
            assert timing is None, log
            timing = index
            values.update(zip(['real_seconds', 'user_seconds', 'sys_seconds'],
                              map(float, match.groups())))
        elif timing is not None:
            match = re.match(r'^\s*(\d+)\s{2,}(.+?)\s*$', line)
            assert match is not None, (log, line)
            values[match.group(2).replace(' ', '_')] = int(match.group(1))
    assert timing is not None and 'maximum_resident_set_size' in values, log
    return {'counters': values, 'raw_time_output': '\n'.join(lines[timing:])}


def timed(command, log, additions):
    started_at = datetime.now(timezone.utc).isoformat()
    command = ['/usr/bin/time', '-l', *command]
    # Explicit benchmark parameters below must not inherit another experiment's settings.
    env = {key: value for key, value in os.environ.items()
           if not key.startswith(('LOGEX_BENCH_', 'LOGEX_PUBLICATION_', 'LOGEX_INLIST_'))}
    env.update({'TMPDIR': '/private/tmp', **additions})
    with log.open('w') as stream:
        result = subprocess.run(command, stdout=stream, stderr=subprocess.STDOUT, env=env)
    return {'command': command, 'started_at_utc': started_at,
            'finished_at_utc': datetime.now(timezone.utc).isoformat(),
            'environment_overrides': additions, 'exit': result.returncode,
            'log': str(log), 'log_sha256': sha(log), **counters(log)}


assert sha(Path(PLAN['binary'])) == PLAN['binary_sha256']
assert Counter(order[0] for order in PLAN['process_order']) == {'A': 10, 'B': 10}
metadata = {'comparison_type': 'same_candidate_executable_A_A', 'plan': PLAN,
    'recorded_at_utc': datetime.now(timezone.utc).isoformat(),
    'runner_source': Path(__file__).read_text(), 'runner_sha256': sha(Path(__file__)),
    'plan_sha256': sha(MANIFEST), 'hardware': output(['sysctl', '-n', 'hw.model', 'hw.memsize', 'hw.ncpu']),
    'os': output(['sw_vers']), 'rustc': output(['rustc', '-Vv']), 'filesystem': output(['df', '-h', '/private/tmp'])}
(ROOT / 'environment.json').write_text(json.dumps(metadata))
suite = PLAN['suite']
retained = []
for pair, order in enumerate(PLAN['process_order']):
    for label in order:
        log = ROOT / f'{pair}-{label}.log'
        command = [PLAN['binary'], suite['test'], '--exact', '--ignored', '--nocapture', '--test-threads=1']
        run = {'kind': 'run', 'pair': pair, 'label': label, **timed(command, log, suite['environment'])}
        append(ROOT / 'results.jsonl', run)
        assert run['exit'] == 0, log
        parsed = []
        for line in log.read_text().splitlines():
            if '{' not in line:
                continue
            try:
                raw = json.loads(line[line.index('{'):])
            except json.JSONDecodeError:
                continue
            record = {'kind': 'fixture_record', 'pair': pair, 'label': label, 'raw_record': raw}
            append(ROOT / 'results.jsonl', record)
            parsed.append(record)
        samples = [r['raw_record'] for r in parsed if r['raw_record'].get('kind') == 'sample']
        assert Counter(s['metric'] for s in samples) == Counter(suite['samples_per_process'])
        assert sum(r['raw_record'].get('kind') == 'config' for r in parsed) == 1
        for metric, n in suite['samples_per_process'].items():
            assert len({s['iteration'] for s in samples if s['metric'] == metric}) == n
        rss = {'kind': 'fixture_record', 'pair': pair, 'label': label,
               'raw_record': {'kind': 'rss', 'bytes': run['counters']['maximum_resident_set_size']}}
        append(ROOT / 'results.jsonl', rss)
        parsed.append(rss)
        retained.extend(parsed)
        print(pair, label, 'same-executable samples retained', flush=True)
configs = [r['raw_record'] for r in retained if r['raw_record'].get('kind') == 'config']
assert len(configs) == 40 and len({json.dumps(c, sort_keys=True) for c in configs}) == 1
for metric in [*suite['samples_per_process'], 'peak_rss']:
    values = {}
    for label in ('A', 'B'):
        raw = [r['raw_record'] for r in retained if r['label'] == label]
        v = [r['bytes'] for r in raw if r.get('kind') == 'rss'] if metric == 'peak_rss' else [r['elapsed_ms'] for r in raw if r.get('kind') == 'sample' and r['metric'] == metric]
        assert len(v) == (20 if metric == 'peak_rss' else 20 * suite['samples_per_process'][metric])
        values[label] = stats(v)
    summary = {'kind': 'same_binary_comparison', 'metric': metric, 'values': values}
    for measure in ('median', 'p95'):
        summary[measure + '_change_percent'] = 100 * (values['B'][measure] / values['A'][measure] - 1)
    append(ROOT / 'results.jsonl', summary)
    print(summary, flush=True)
metadata['retained_counts'] = dict(Counter(r['raw_record']['kind'] for r in retained))
assert metadata['retained_counts']['sample'] == PLAN['expected_samples']
assert metadata['retained_counts']['rss'] == PLAN['expected_rss']
metadata['results_sha256'] = sha(ROOT / 'results.jsonl')
(ROOT / 'environment.json').write_text(json.dumps(metadata))
print('Complete:', metadata['retained_counts'], flush=True)

