"""Verify and retain the initial and fixed confirmation measurements together."""
from pathlib import Path
from collections import Counter
import gzip
import hashlib
import json
import math
import re
import statistics
import sys

INITIAL, CONFIRMATION = map(Path, sys.argv[1:3])
OUT = Path('/Users/tdenisenko/code/logex/docs/audit/baselines')
PREFIX = '2026-09-13-sql-grouping-aggregates-'


def digest(data):
    return hashlib.sha256(data).hexdigest()


def read(root):
    return json.loads((root / 'environment.json').read_text())


def stats(values):
    assert values and all(math.isfinite(v) and v >= 0 for v in values)
    return {'samples': len(values), 'median': statistics.median(values),
            'p95': sorted(values)[math.ceil(len(values) * .95) - 1]}


def save(name, data):
    path = OUT / (PREFIX + name)
    assert not path.exists(), path
    if name.endswith('.gz'):
        encoded = gzip.compress(data, mtime=0)
        assert gzip.decompress(encoded) == data
    else:
        encoded = data
    path.write_bytes(encoded)
    return {'file': path.name, 'bytes': len(encoded), 'sha256': digest(encoded),
            'decoded_sha256': digest(data), 'decoded_bytes': len(data)}


def validate(root, environment, samples_expected, processes_expected):
    raw = (root / 'results.jsonl').read_bytes()
    assert digest(raw) == environment['results.jsonl']['sha256']
    data = [json.loads(line) for line in raw.splitlines()]
    fixtures = [r for r in data if r['kind'] == 'fixture_record']
    runs = [r for r in data if r['kind'] == 'run']
    assert len(runs) == processes_expected
    assert len({(r['suite'], r['pair'], r['revision']) for r in runs}) == processes_expected
    assert sum(r['raw_record'].get('kind') == 'sample' for r in fixtures) == samples_expected
    assert sum(r['raw_record'].get('kind') == 'rss' for r in fixtures) == processes_expected
    suites = {s['name']: s for s in environment['plan']['benchmarks']}
    for run in runs:
        assert run['exit'] == 0
        output = Path(run['log']).read_text()
        assert digest(output.encode()) == run['log_sha256']
        run['output'] = output
        emitted = []
        for line in output.splitlines():
            if '{' in line:
                try:
                    emitted.append(json.loads(line[line.index('{'):]))
                except json.JSONDecodeError:
                    pass
        matching = [r['raw_record'] for r in fixtures
                    if all(r[k] == run[k] for k in ('suite', 'pair', 'revision'))]
        assert [r for r in matching if r.get('kind') != 'rss'] == emitted
        rss = re.findall(r'^\s*(\d+)\s+maximum resident set size\s*$', output, re.M)
        assert len(rss) == 1
        assert int(rss[0]) == run['counters']['maximum_resident_set_size']
        assert [r for r in matching if r.get('kind') == 'rss'] == [{'kind': 'rss', 'bytes': int(rss[0])}]
        suite = suites[run['suite']]
        samples = [r for r in matching if r.get('kind') == 'sample']
        assert Counter(r['metric'] for r in samples) == Counter(suite['samples_per_process'])
        for metric, expected in suite['samples_per_process'].items():
            assert len({r['iteration'] for r in samples if r['metric'] == metric}) == expected
        assert run['environment_overrides'] == suite['environment']
    for name in suites:
        selected = [r for r in runs if r['suite'] == name]
        suite = suites[name]
        order = suite.get('process_order', [list(('base', 'candidate') if p % 2 == 0 else ('candidate', 'base')) for p in range(5)])
        assert [(r['pair'], r['revision']) for r in selected] == [(p, label) for p, labels in enumerate(order) for label in labels]
        configs = [r['raw_record'] for r in fixtures if r['suite'] == name and r['raw_record'].get('kind') == 'config']
        assert len(configs) == len(selected)
        assert len({json.dumps(c, sort_keys=True) for c in configs}) == 1
    for summary in (r for r in data if r['kind'] in ('process_summary', 'comparison')):
        labels = ('base', 'candidate') if summary['kind'] == 'comparison' else (summary['revision'],)
        calculated = {}
        for label in labels:
            matching = [r['raw_record'] for r in fixtures if r['suite'] == summary['suite']
                        and r['revision'] == label and (summary['kind'] == 'comparison' or r['pair'] == summary['pair'])]
            calculated[label] = stats(values(matching, summary['metric']))
        if summary['kind'] == 'process_summary':
            assert calculated[summary['revision']] == {k: summary[k] for k in ('samples', 'median', 'p95')}
        else:
            assert calculated == summary['values']
            for measure in ('median', 'p95'):
                change = 100 * (calculated['candidate'][measure] / calculated['base'][measure] - 1)
                assert math.isclose(change, summary[measure + '_change_percent'], abs_tol=1e-12)
    return raw, fixtures, runs, [r for r in data if r['kind'] == 'comparison']


def values(records, metric):
    return ([r['bytes'] for r in records if r.get('kind') == 'rss'] if metric == 'peak_rss'
            else [r['elapsed_ms'] for r in records if r.get('kind') == 'sample' and r['metric'] == metric])


initial, confirmation = read(INITIAL), read(CONFIRMATION)
assert confirmation['original_environment_sha256'] == digest((INITIAL / 'environment.json').read_bytes())
assert initial['candidate_commit'] == confirmation['candidate_commit']
assert initial['base_commit'] == confirmation['base_commit']
assert confirmation['plan']['confirmation']['initial_results_sha256'] == initial['results.jsonl']['sha256']
for target, expected in confirmation['binaries'].items():
    assert expected == initial['binary_comparisons'][target]
    for label, checksum in expected['sha256'].items():
        with (INITIAL / f'{label}-{target}').open('rb') as stream:
            assert hashlib.file_digest(stream, 'sha256').hexdigest() == checksum
raw_first, rows_first, runs_first, summaries_first = validate(INITIAL, initial, 39_500, 80)
raw_next, rows_next, runs_next, summaries_next = validate(CONFIRMATION, confirmation, 16_000, 160)
for suite in confirmation['plan']['benchmarks']:
    for field in ('environment', 'samples_per_process', 'test', 'target'):
        assert suite[field] == next(s for s in initial['plan']['benchmarks'] if s['name'] == suite['name'])[field]
    configs = [r['raw_record'] for r in rows_first + rows_next if r['suite'] == suite['name'] and r['raw_record'].get('kind') == 'config']
    assert len({json.dumps(c, sort_keys=True) for c in configs}) == 1
combined = []
for summary in summaries_first:
    result = {'suite': summary['suite'], 'metric': summary['metric'], 'values': {}}
    for label in ('base', 'candidate'):
        selected = [r['raw_record'] for r in rows_first + rows_next if r['suite'] == summary['suite'] and r['revision'] == label]
        result['values'][label] = stats(values(selected, summary['metric']))
    for measure in ('median', 'p95'):
        result[measure + '_change_percent'] = 100 * (result['values']['candidate'][measure] / result['values']['base'][measure] - 1)
    combined.append(result)
files = [save('confirmation-final.jsonl.gz', raw_next),
         save('confirmation-run-logs.json.gz', json.dumps(runs_next, indent=2).encode())]
report = {'environment': confirmation, 'initial_environment_sha256': digest((INITIAL / 'environment.json').read_bytes()),
          'verification_script': Path(__file__).read_text(), 'verification_script_sha256': digest(Path(__file__).read_bytes()),
          'retained_samples': 55_500, 'retained_rss': 240,
          'initial': summaries_first, 'confirmation': summaries_next, 'combined': combined, 'files': files,
          'verification': 'Original logs, emitted records, expected configurations, predefined process order, executable hashes, every sample, process counter and all summaries independently checked. No original observations excluded. Five initial pairs plus twenty fixed confirmation pairs per affected workload. Unaffected workloads retain their initial five pairs.'}
save('confirmation.json', (json.dumps(report, indent=2) + '\n').encode())
for section in ('confirmation', 'combined'):
    print(section)
    for r in report[section]:
        print(r['suite'], r['metric'], round(r['median_change_percent'], 3), round(r['p95_change_percent'], 3))
